/**
 * @param {Array} keysArr
 * @param {Array} valuesArr
 * @return {Object}
 */
var createObject = function(keysArr, valuesArr) {
    const obj = {};
    for (let i = 0; i < keysArr.length; i++) {
        const key = String(keysArr[i]);                          // non-strings are converted
        if (!Object.prototype.hasOwnProperty.call(obj, key)) {   // only the first occurrence counts
            obj[key] = valuesArr[i];
        }
    }
    return obj;
};
